using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace T2TOnline.Core.Lobby;

/// <summary>
/// How a word is laid out: how much room it has. <c>tools/checks/lobbywords_check.py</c> measures each against its limit.
/// </summary>
public enum WordFit
{
    /// <summary>A sentence: a prompt's body or a toast. It wraps.</summary>
    Sentence,

    /// <summary>A button on the title's list: 36 high, no auto-size, no wrap.</summary>
    TitleRow,

    /// <summary>A menu's header, in the header font: it auto-sizes.</summary>
    Header,

    /// <summary>A prompt in the bottom bar, or a button in a list.</summary>
    Prompt,

    /// <summary>A label on a seat's card or a list row's detail: a narrow space, one or two lines.</summary>
    Seat,

    /// <summary>A tab of the game's Settings menu (the eight tabs share one 1920 bar): NotoSans-Black 26, one line, in about 177 px of text.</summary>
    SettingsTab,

    /// <summary>A Settings row's title (or its second line, which is smaller): NotoSans-SemiBoldItalic 24, one line, in the row's 600 px.</summary>
    SettingsRow,

    /// <summary>The text of a Settings button row's button: NotoSans-Black 24, one line, in the button's 360 px less a margin.</summary>
    SettingsButton,

    /// <summary>A Settings tooltip's description: NotoSans-SemiBoldItalic 18, wrapped in 312 px, in a box that shows four lines and scrolls the rest by itself.</summary>
    SettingsTooltip,

    /// <summary>A tab of a Glossary-framed screen (the Join list's frame): NotoSans-Black, spaced, one line, in about 243 px of text.</summary>
    ListTab,
}

/// <summary>One of the mod's words in the game's 15 languages (<see cref="LobbyWords"/>), with its term for the game's localization source.</summary>
public sealed class LobbyWord
{
    private readonly string[] _texts;

    internal LobbyWord(string key, WordFit fit, string[] texts)
    {
        Key = key;
        Fit = fit;
        _texts = texts;
    }

    /// <summary>Its term in the game's localization source (<c>t2t/...</c>), added there at run time.</summary>
    public string Key { get; }

    /// <summary>How it's laid out.</summary>
    public WordFit Fit { get; }

    /// <summary>Its text in each language, in the game's order (<see cref="LobbyWords.Languages"/>).</summary>
    public IReadOnlyList<string> Texts => _texts;

    /// <summary>Its text in <paramref name="language"/>, with <c>{0}</c>, <c>{1}</c>... filled in. An index it doesn't know gives English. Never throws.</summary>
    public string Text(int language, params string[] args)
    {
        string text = (uint)language < (uint)_texts.Length ? _texts[language] : _texts[0];
        return LobbyWords.Fill(text, args);
    }
}

/// <summary>A word to show with its arguments: a term of the mod's or of the game's, so screens and tests don't care which.</summary>
/// <param name="Term">The term (<see cref="LobbyWord.Key"/>, or a game's from <see cref="LobbyTerms"/>).</param>
/// <param name="Args">What goes in its <c>{0}</c>, <c>{1}</c>...: names (cleaned, <see cref="DisplayName"/>) and numbers.</param>
public sealed record LobbyLine(string Term, IReadOnlyList<string> Args)
{
    /// <summary>What goes in its <c>{0}</c>, <c>{1}</c>...; never null.</summary>
    public IReadOnlyList<string> Args { get; init; } = Args ?? Array.Empty<string>();

    /// <summary>A word with arguments.</summary>
    public LobbyLine(LobbyWord word, params string[] args)
        : this(word?.Key ?? string.Empty, args)
    {
    }

    /// <summary>A game's term with arguments.</summary>
    public static LobbyLine Game(string term, params string[] args) => new(term, (IReadOnlyList<string>)args);

    /// <summary>The same term and arguments: a screen redraws only when its line really changed.</summary>
    public bool Equals(LobbyLine? other)
    {
        if (ReferenceEquals(this, other))
        {
            return true;
        }

        if (other == null || !string.Equals(Term, other.Term, StringComparison.Ordinal) || Args.Count != other.Args.Count)
        {
            return false;
        }

        for (int i = 0; i < Args.Count; i++)
        {
            if (!string.Equals(Args[i], other.Args[i], StringComparison.Ordinal))
            {
                return false;
            }
        }

        return true;
    }

    /// <inheritdoc/>
    public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Term);

    /// <summary>The same line for a text with rich text on (the game's prompts): each argument kept from being read as tags. Names are untrusted, and a label of ours has rich text off.</summary>
    public LobbyLine ForRichText()
    {
        var safe = new string[Args.Count];
        for (int i = 0; i < safe.Length; i++)
        {
            safe[i] = DisplayName.ForRichText(Args[i]);
        }

        return new LobbyLine(Term, safe);
    }

    /// <summary>
    /// The line in <paramref name="language"/>. A term of the mod's comes from <see cref="LobbyWords"/>; a game's from
    /// <paramref name="gameTerm"/> (the plugin's <c>LocalizationManager</c> read), and without one it shows nothing rather than a term's name.
    /// </summary>
    public string Text(int language, Func<string, string?>? gameTerm = null)
    {
        if (LobbyWords.Find(Term) is { } word)
        {
            return LobbyWords.Fill((uint)language < LobbyWords.LanguageCount ? word.Texts[language] : word.Texts[0], Args);
        }

        return LobbyWords.Fill(gameTerm?.Invoke(Term) ?? string.Empty, Args);
    }
}

/// <summary>
/// Everything the native lobby says that the game has no word for, in the game's 15 languages and in its order. Added to the
/// game's own source at run time as <c>t2t/*</c> terms (<c>LanguageSourceData.AddTerm</c>), so cloned labels follow a language
/// change by themselves. What the game does have a word for is in <see cref="LobbyTerms"/>, and is never copied here.
/// </summary>
/// <remarks>
/// Drafted translations, not yet reviewed by native speakers: short, plain, in the game's own vocabulary where it has one
/// (the run is "aventure" in French, "matka" in Finnish, "výprava" in Czech; French is Canadian and says "vous", as the game
/// does). Until a native speaker has read them (<see cref="TranslationsReviewed"/>), a word may read oddly; fix on report.
/// The Chinese and Japanese atlases are static, and every string must be drawable: zh invite is 拉好友 and ja invite is 呼ぶ
/// because 邀, 招 and 誘 are in no atlas. <c>tools/checks/lobbywords_check.py</c> reads this file and checks every glyph and
/// width against the game's fonts. Each word stays on one line: that tool reads them by line.
/// </remarks>
public static class LobbyWords
{
    /// <summary>The languages, as many as the game has.</summary>
