    /// <summary>Every word, in this file's order.</summary>
    public static IReadOnlyList<LobbyWord> All => Table;

    /// <summary>The word with this term, or null: a game's term, or nothing of ours.</summary>
    public static LobbyWord? Find(string? key) => key != null && ByKey.TryGetValue(key, out LobbyWord? word) ? word : null;

    /// <summary>
    /// <paramref name="text"/> with <c>{0}</c>, <c>{1}</c>... replaced: an argument that isn't there leaves its mark, and a
    /// name holding braces stays as it is. Never throws, unlike <c>string.Format</c> on a translation with a stray brace.
    /// </summary>
    public static string Fill(string text, IReadOnlyList<string>? args)
    {
        if (string.IsNullOrEmpty(text) || args == null || args.Count == 0 || text.IndexOf('{', StringComparison.Ordinal) < 0)
        {
            return text ?? string.Empty;
        }

        var filled = new StringBuilder(text.Length + 16);
        for (int i = 0; i < text.Length; i++)
        {
            if (text[i] == '{' && i + 2 < text.Length && text[i + 1] is >= '0' and <= '9' && text[i + 2] == '}' && text[i + 1] - '0' < args.Count)
            {
                filled.Append(args[text[i + 1] - '0']);
                i += 2;
            }
            else
            {
                filled.Append(text[i]);
            }
        }

        return filled.ToString();
    }

    /// <summary>A number the way a word's argument wants it, whatever this PC's culture.</summary>
    public static string Number(int value) => value.ToString(CultureInfo.InvariantCulture);

    private static LobbyWord W(string key, WordFit fit, params string[] texts)
    {
        var word = new LobbyWord(key, fit, texts);
        Table.Add(word);
        ByKey[key] = word;
        return word;
    }
